CREATE FUNCTION ficha_producto(p_sku text) RETURNS text
LANGUAGE plpgsql STABLE AS $$
DECLARE
  v_prod productos%ROWTYPE;
  v_cat  record;
BEGIN
  SELECT * INTO v_prod FROM productos WHERE sku = p_sku;
  IF NOT FOUND THEN
    RETURN 'No existe el producto ' || p_sku;
  END IF;
  SELECT c.nombre, padre.nombre AS padre INTO v_cat
  FROM categorias c LEFT JOIN categorias padre ON padre.id = c.padre_id
  WHERE c.id = v_prod.categoria_id;
  RETURN format('%s | %s > %s | $%s | stock %s',
                v_prod.nombre, v_cat.padre, v_cat.nombre, v_prod.precio, v_prod.stock);
END $$;
