LANGUAGE plpgsql IMMUTABLE AS $$
BEGIN
  IF p_total IS NULL OR p_region IS NULL THEN
    RETURN NULL;
  ELSIF p_total >= 50000 THEN
    RETURN 0;
  ELSIF p_region = 'Metropolitana' THEN
