CREATE FUNCTION ticket_promedio(p_cliente_id integer) RETURNS integer
LANGUAGE plpgsql STABLE AS $$
DECLARE
  v_total   bigint;
  v_pedidos integer;
BEGIN
  SELECT coalesce(sum(i.cantidad * i.precio_unitario), 0), count(DISTINCT p.id)
  INTO v_total, v_pedidos
  FROM pedidos p JOIN pedido_items i ON i.pedido_id = p.id
  WHERE p.cliente_id = p_cliente_id;
  RETURN v_total / v_pedidos;
END $$;
