CREATE FUNCTION cuotas(p_monto integer, p_n integer)
RETURNS TABLE (cuota integer, vence date, valor integer)
LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE
  v_base integer := p_monto / p_n;
BEGIN
  FOR i IN 1..p_n LOOP
    cuota := i;
    vence := DATE '2026-10-05' + make_interval(months => i - 1);
    valor := CASE WHEN i = p_n THEN p_monto - v_base * (p_n - 1) ELSE v_base END;
    RETURN NEXT;
  END LOOP;
END $$;
SELECT * FROM cuotas(549990, 3);
SELECT * FROM cuotas(100000, 7);
SELECT count(*) AS cuotas, sum(valor) AS total FROM cuotas(100000, 7);

