CREATE FUNCTION prestar(p_socio_id integer, p_libro_id integer) RETURNS integer
LANGUAGE plpgsql AS $$
DECLARE
  v_libro libros%ROWTYPE;
  v_fuera integer;
  v_id    integer;
BEGIN
  SELECT * INTO v_libro FROM libros WHERE id = p_libro_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'no existe el libro %', p_libro_id
      USING ERRCODE = 'no_data_found';
  END IF;
  SELECT count(*) INTO v_fuera
  FROM prestamos
  WHERE libro_id = p_libro_id AND fecha_devolucion IS NULL;
  IF v_fuera >= v_libro.ejemplares THEN
    RAISE EXCEPTION 'no quedan ejemplares de «%»', v_libro.titulo
      USING DETAIL = format('Tiene %s ejemplares y %s están prestados.', v_libro.ejemplares, v_fuera),
            HINT = 'Ofrece una reserva o revisa los préstamos sin devolver.';
  END IF;
  INSERT INTO prestamos (libro_id, socio_id, fecha_prestamo, fecha_limite)
  VALUES (p_libro_id, p_socio_id, current_date, current_date + 14)
  RETURNING id INTO v_id;
  RETURN v_id;
END $$;
