CREATE FUNCTION reajustar_precios(p_categoria_id integer, p_pct numeric) RETURNS integer
LANGUAGE plpgsql AS $$
DECLARE
  v_filas integer;
BEGIN
  UPDATE productos
  SET precio = round(precio * (1 + p_pct / 100))
  WHERE categoria_id = p_categoria_id AND activo;
  GET DIAGNOSTICS v_filas = ROW_COUNT;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'la categoría % no tiene productos activos', p_categoria_id
      USING ERRCODE = 'no_data_found',
            HINT = 'Las categorías padre (como Tecnología) no tienen productos directos.';
  END IF;
  RAISE NOTICE 'reajustados % productos en % %%', v_filas, p_pct;
  RETURN v_filas;
END $$;
