CREATE TABLE resenas_archivo (LIKE resenas);
CREATE PROCEDURE archivar_resenas(p_hasta date, p_lote integer DEFAULT 100)
LANGUAGE plpgsql AS $$
DECLARE
  v_filas integer;
  v_lote  integer := 0;
BEGIN
  LOOP
    WITH movidas AS (
      DELETE FROM resenas
      WHERE id IN (SELECT id FROM resenas WHERE fecha < p_hasta ORDER BY id LIMIT p_lote)
      RETURNING *
    )
    INSERT INTO resenas_archivo SELECT * FROM movidas;
    GET DIAGNOSTICS v_filas = ROW_COUNT;
    EXIT WHEN v_filas = 0;
    v_lote := v_lote + 1;
    RAISE NOTICE 'lote %: % reseñas (transacción %)', v_lote, v_filas, pg_current_xact_id();
    COMMIT;
  END LOOP;
END $$;
CALL archivar_resenas('2025-07-01', 10);
SELECT xmin, count(*) AS filas FROM resenas_archivo GROUP BY xmin ORDER BY xmin::text::bigint;
