CREATE FUNCTION concepto(p_nota numeric) RETURNS text
LANGUAGE plpgsql IMMUTABLE
AS $$
BEGIN
  IF p_nota IS NULL THEN
    RETURN 'Sin nota';
  ELSIF p_nota < 1.0 OR p_nota > 7.0 THEN
    RAISE EXCEPTION 'nota fuera de la escala 1.0 a 7.0: %', p_nota
      USING ERRCODE = 'invalid_parameter_value';
  ELSIF p_nota < 4.0 THEN
    RETURN 'Insuficiente';
  ELSIF p_nota < 5.0 THEN
    RETURN 'Suficiente';
  ELSIF p_nota < 6.0 THEN
    RETURN 'Bueno';
  ELSE
    RETURN 'Muy bueno';
  END IF;
END $$;

