CREATE FUNCTION registrar_venta(p_sku text, p_cantidad integer) RETURNS integer
LANGUAGE plpgsql AS $$
DECLARE
  v_stock productos.stock%TYPE;
BEGIN
  IF p_cantidad IS NULL OR p_cantidad <= 0 THEN
    RAISE EXCEPTION 'cantidad inválida: %', p_cantidad
      USING ERRCODE = 'invalid_parameter_value';
  END IF;
  SELECT stock INTO v_stock FROM productos WHERE sku = p_sku FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'no existe el producto %', p_sku
      USING ERRCODE = 'no_data_found';
  END IF;
  IF v_stock < p_cantidad THEN
    RAISE EXCEPTION 'stock insuficiente para %: se piden % unidades', p_sku, p_cantidad
      USING HINT = format('Quedan %s unidades.', v_stock);
  END IF;
  UPDATE productos SET stock = stock - p_cantidad WHERE sku = p_sku;
  RETURN v_stock - p_cantidad;
END $$;

