CREATE FUNCTION dias_habiles(p_desde date, p_hasta date) RETURNS integer
LANGUAGE plpgsql STABLE STRICT
AS $$
DECLARE
  v_dia   date := p_desde;
  v_total integer := 0;
BEGIN
  WHILE v_dia <= p_hasta LOOP
    IF extract(isodow FROM v_dia) < 6
       AND NOT EXISTS (SELECT 1 FROM feriados WHERE fecha = v_dia) THEN
      v_total := v_total + 1;
    END IF;
    v_dia := v_dia + 1;
  END LOOP;
  RETURN v_total;
END $$;

