CREATE FUNCTION cargar_productos() RETURNS integer
LANGUAGE plpgsql AS $$
DECLARE
  r        productos_import%ROWTYPE;
  v_ok     integer := 0;
  v_estado text;
  v_msg    text;
BEGIN
  FOR r IN SELECT * FROM productos_import ORDER BY linea LOOP
    BEGIN
      INSERT INTO productos (sku, nombre, categoria_id, precio, costo, creado_en)
      VALUES (r.sku, r.nombre,
              (SELECT id FROM categorias WHERE nombre = r.categoria),
              r.precio::integer, r.costo::integer, current_date);
      v_ok := v_ok + 1;
    EXCEPTION WHEN OTHERS THEN
      GET STACKED DIAGNOSTICS v_estado = RETURNED_SQLSTATE, v_msg = MESSAGE_TEXT;
      INSERT INTO errores_carga (linea, sqlstate, mensaje) VALUES (r.linea, v_estado, v_msg);
    END;
  END LOOP;
  RETURN v_ok;
END $$;
SELECT cargar_productos();

