exercises.solution:
CREATE FUNCTION emitir_boleta(p_pedido_id integer) RETURNS integer
LANGUAGE plpgsql AS $$
DECLARE
  v_estado text;
  v_total  integer;
  v_neto   integer;
  v_folio  integer;
BEGIN
  SELECT folio INTO v_folio FROM boletas WHERE pedido_id = p_pedido_id;
  IF FOUND THEN
    RETURN v_folio;
  END IF;
  SELECT estado INTO v_estado FROM pedidos WHERE id = p_pedido_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'no existe el pedido %', p_pedido_id USING ERRCODE = 'BL001';
  END IF;
  IF v_estado NOT IN ('pagado', 'enviado', 'entregado') THEN
    RAISE EXCEPTION 'el pedido % está %', p_pedido_id, v_estado
      USING ERRCODE = 'BL002',
            HINT = 'Solo se emiten boletas de pedidos pagados, enviados o entregados.';
  END IF;
  SELECT sum(i.cantidad * i.precio_unitario) + p.costo_despacho INTO v_total
  FROM pedidos p JOIN pedido_items i ON i.pedido_id = p.id
  WHERE p.id = p_pedido_id
  GROUP BY p.costo_despacho;
  v_neto := round(v_total / 1.19);
  INSERT INTO boletas (pedido_id, neto, iva, total)
  VALUES (p_pedido_id, v_neto, v_total - v_neto, v_total)
  RETURNING folio INTO v_folio;
  RETURN v_folio;
END $$;

