CREATE PROCEDURE cerrar_mes(p_mes date, p_lote integer DEFAULT 50)
LANGUAGE plpgsql AS $$
DECLARE
  v_filas integer;
  v_lote  integer := 0;
BEGIN
  IF p_mes IS NULL OR extract(day FROM p_mes) <> 1 THEN
    RAISE EXCEPTION 'p_mes debe ser el primer día de un mes: %', p_mes
      USING ERRCODE = 'invalid_parameter_value';
  END IF;
  IF EXISTS (SELECT 1 FROM cierres_mes WHERE mes = p_mes) THEN
    RAISE EXCEPTION 'el mes % ya está cerrado', to_char(p_mes, 'YYYY-MM')
      USING HINT = 'Revisa la tabla cierres_mes.';
  END IF;
  LOOP
    UPDATE pedidos SET cerrado = true
    WHERE id IN (SELECT id FROM pedidos
                 WHERE NOT cerrado AND estado = 'entregado'
                   AND fecha >= p_mes AND fecha < p_mes + interval '1 month'
                 ORDER BY id
                 LIMIT p_lote);
    GET DIAGNOSTICS v_filas = ROW_COUNT;
    EXIT WHEN v_filas = 0;
    v_lote := v_lote + 1;
    RAISE NOTICE 'lote %: % pedidos cerrados', v_lote, v_filas;
    COMMIT;
  END LOOP;
  INSERT INTO cierres_mes (mes, pedidos, total)
  SELECT p_mes, count(DISTINCT p.id), coalesce(sum(i.cantidad * i.precio_unitario), 0)
  FROM pedidos p JOIN pedido_items i ON i.pedido_id = p.id
  WHERE p.cerrado AND p.fecha >= p_mes AND p.fecha < p_mes + interval '1 month';
  COMMIT;
END $$;
